INSERT INTO `exams` VALUES (2,1,'NEET Exam','2025-08-14','2025-06-07',30,'A',30,30,'General Instructions\n\n1. The exam is objective type (Multiple Choice Questions – MCQs).\n2. Each question has 4 options, out of which only one option is correct.\n3. Select the correct option by clicking on the radio button/checkbox provided.\n4. Once selected, you can change your answer before final submission.\n5. Each question carries equal marks. No negative marking (if applicable).\n\nSystem Instructions\n\n6. The exam is time-bound. Timer will start as soon as you begin.\n7. Do not refresh, close, or switch tabs during the exam, otherwise you may get auto-logged out.\n8. Your answers are auto-saved after each selection.\n9. After completion, click on Submit to finalize your answers.\n10. If the exam time ends, the system will auto-submit your paper.\n\nImportant\n\n11. Do not try to open any other application or website during the exam.\n12. Any attempt of malpractice will result in immediate disqualification.\n13. Keep your internet connection stable.',NULL,15),(13,1,'Common ETC','2025-12-07','2025-12-07',1,'A',30,30,'General Instructions\n \n 1. The exam is objective type (Multiple Choice Questions – MCQs).\n 2. Each question has 4 options, out of which only one option is correct.\n 3. Select the correct option by clicking on the radio button/checkbox provided.\n 4. Once selected, you can change your answer before final submission.\n 5. Each question carries equal marks. No negative marking (if applicable).\n',NULL,15);
