INSERT INTO `questions` VALUES (1279,NULL,'Drift velocity (vd​) is related to current density (J) by:','vd​=Jne','vd​=neJ​','vd​=Jne​','vd​=meEτ​',NULL,NULL,'A',2,NULL,NULL,NULL,'English',3,-0.25,'3',NULL,NULL,'Yes',NULL,'Ques_img_1.png',NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1280,NULL,'A solenoid with 15 turns/cm and 2.0 cm2 loop area. Current changes from 2.0 A to 4.0 A in 0.1 s. Induced EMF is:','6.03×10−6 V','1.51×10−6 V','3.016×10−6 V','30.16 mV',NULL,NULL,'B',2,NULL,NULL,NULL,'English',5,-0.25,'5',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1281,NULL,'Huygens\' Principle is used to prove:','Snell\'s Law only','Ohm\'s Law','Reflection and refraction laws','Inverse square law',NULL,NULL,'D',2,NULL,NULL,NULL,'English',4,-0.25,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1282,NULL,'If peak voltage of an AC source is V0​, the RMS voltage is:','V0​2​','2V0​​','2​V0​​','V0​',NULL,NULL,'B',2,NULL,NULL,NULL,'English',2,-0.25,'2',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1283,NULL,'Which is NOT a necessary condition for Total Internal Reflection (TIR)?','∠i>∠c','Light travels Denser to Rarer','μ1​=μ2​','Light passes through interface',NULL,NULL,'D',2,NULL,NULL,NULL,'English',3,-0.25,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1284,NULL,'In forward bias of a p-n junction diode, the depletion region width:','Increases','Decreases','Remains same','Vanishes completely',NULL,NULL,'A',2,NULL,NULL,NULL,'English',4,-0.25,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1285,NULL,'The difference between the mass of a nucleus and the sum of masses of its nucleons is called:','Binding energy','Mass defect','Nuclear defect','Isotope mass',NULL,NULL,'A',2,NULL,NULL,NULL,'English',3,-0.25,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Physics'),(1286,NULL,'YDSE: D=1.0 m, λ=6000 A˚, Angular fringe width θ=0.2∘. Slit spacing (d) is:','1.72×10−3 m','3.45×10−4 m','1.72×10−4 m','3.45×10−3 m',NULL,NULL,'C',2,NULL,NULL,NULL,'English',5,-0.25,'6',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Physics'),(1287,NULL,'The working principle of a transformer is:','Self Induction','Mutual Induction','Eddy Currents','Joule Heating',NULL,NULL,'C',2,NULL,NULL,NULL,'English',5,-0.25,'5',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Physics'),(1288,NULL,'Capacitance of a parallel plate capacitor with a dielectric slab (t<d, constant K) is:','dKϵ0​A​','d−t+t/Kϵ0​A​','d−t+Ktϵ0​A​','d(K+1)ϵ0​A​',NULL,NULL,'D',2,NULL,NULL,NULL,'English',5,NULL,'6',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Physics'),(1289,NULL,'A factory produces two items, X and Y, using two machines, M1 and M2.\nEach unit of X requires 1 hour on M1 and 2 hours on M2.\nEach unit of Y requires 2 hours on M1 and 1 hour on M2.\nMachine M1 is available for a maximum of 160 hours per week, while M2 is available for 140 hours per week.\nThe manufacturer must produce at least 30 units of X and at least 20 units of Y to meet weekly demand.\nThe profit on each unit of X is ₹60, while the profit on each unit of Y is ₹80.\nForm the system of linear inequalities representing the constraints.\nWrite the objective function to maximize profit.\nThen determine the maximum profit using the corner-point method.\nWhat is the maximum profit?','₹7,200','₹8,000','₹8,600','₹9,200',NULL,NULL,'D',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,'Ques_img_11.png',NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1290,NULL,'Particular solution of dxdy​=(1+x)(1+y) with y(0)=0:','y=ex+x2−1','$\\ln','1+y','#ERROR!',NULL,NULL,'D',2,NULL,NULL,NULL,'English',4,NULL,'5',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1291,NULL,'Area of parallelogram with sides a=3i^+j^​+4k^ and b=i^−j^​+k^ is:','46​','35​','42​','221​',NULL,NULL,'B',2,NULL,NULL,NULL,'English',3,NULL,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1292,NULL,'Bag: 4 red, 6 black. Two balls drawn without replacement. P(both black) is:','256​','31​','53​','51​',NULL,NULL,'D',2,NULL,NULL,NULL,'English',4,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1293,NULL,'If A=(2−4​−37​), A−1 is:','(74​32​)','(7/22​3/21​)','(1−4​−32​)','(24​37​)',NULL,NULL,'B',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1294,NULL,'The function f(x)=3−4x is:','One-one only','Onto only','Neither one-one nor onto','Bijective',NULL,NULL,'B',2,NULL,NULL,NULL,'English',3,NULL,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Math'),(1295,NULL,'Angle between lines 2x−1​=2y+2​=−1z−3​ and 4x+5​=1y−2​=8z+1​ is:',NULL,NULL,NULL,NULL,NULL,NULL,'C',2,NULL,NULL,NULL,'English',3,NULL,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'NUMERICAL','I','Math'),(1296,NULL,'Maximum value of f(x)=sinx+cosx in [0,π] is:','1','2​','−2​','0',NULL,NULL,'C',2,NULL,NULL,NULL,'English',6,NULL,'6',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Math'),(1297,NULL,'LPP for maximizing profit Z=30x+20y with constraints:','x+2y≤10,x+y≤7','2x+y≤10,x+y≤7','30x+20y≤17','2x+y≥10,x+y≥7',NULL,NULL,'A',2,NULL,NULL,NULL,'English',5,NULL,'5',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Math'),(1298,NULL,'A factory produces two items, X and Y, using two machines, M1 and M2.\nEach unit of X requires 1 hour on M1 and 2 hours on M2.\nEach unit of Y requires 2 hours on M1 and 1 hour on M2.\nMachine M1 is available for a maximum of 160 hours per week, while M2 is available for 140 hours per week.\nThe manufacturer must produce at least 30 units of X and at least 20 units of Y to meet weekly demand.\nThe profit on each unit of X is ₹60, while the profit on each unit of Y is ₹80.\nForm the system of linear inequalities representing the constraints.\nWrite the objective function to maximize profit.\nThen determine the maximum profit using the corner-point method.\nWhat is the maximum profit?',NULL,NULL,NULL,NULL,NULL,NULL,'B',2,NULL,NULL,NULL,'English',6,NULL,'6',NULL,NULL,'Yes',NULL,NULL,'Ques_20_option_a.png','Ques_20_option_b.png','Ques_20_option_c.png','Ques_20_option_d.png','MCQ','II','Math'),(1299,NULL,'Molality is independent of temperature because it involves:','Volume of solution','Moles of solute','Mass of solvent','Molar mass',NULL,NULL,'D',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,'Ques_img_21.png',NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1300,NULL,'Aniline can be converted to phenol via:','Wurtz-Fittig Reaction','Kolbe’s Reaction','Diazotisation followed by hydrolysis','Reimer-Tiemann Reaction',NULL,NULL,'C',2,NULL,NULL,NULL,'English',4,NULL,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1301,NULL,'Transition elements show variable oxidation states due to small energy difference between:','np and nd orbitals','ns and np orbitals','(n−1)d and ns orbitals','nf and (n−1)d orbitals',NULL,NULL,'A',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1302,NULL,'The packing efficiency in a Body-Centered Cubic (BCC) lattice is:','0.74','0.524','0.68','0.62',NULL,NULL,'D',2,NULL,NULL,NULL,'English',4,NULL,'4',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1303,NULL,'Mass of Cu deposited from CuSO4​ solution by passing 2 Faradays of charge:','31.75 g','63.5 g','127.0 g','21.17 g',NULL,NULL,'D',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1304,NULL,'The IUPAC name for K3​[Fe(CN)6​] is:','Potassium hexacyano iron(III)','Potassium hexacyanidoferrate(II)','Potassium hexacyanidoferrate(III)','Tripotassium hexacyanoiron(III)',NULL,NULL,'B',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1305,NULL,'Which statement is TRUE about chemisorption?','Involves Van der Waals forces','Is always reversible','It is irreversible','Heat of adsorption is low',NULL,NULL,'A',2,NULL,NULL,NULL,'English',3,NULL,'3',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','I','Chemistry'),(1306,NULL,'First-order reaction 50% complete in 30 min. Time for 90% completion is:','60 minutes','120 minutes','99.7 minutes','150 minutes',NULL,NULL,'B',2,NULL,NULL,NULL,'English',6,NULL,'6',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Chemistry'),(1307,NULL,'A company manufactures two products, A and B.\nEach unit of A requires 2 hours of labour and 3 units of raw material, while each unit of B requires 3 hours of labour and 2 units of raw material.\nThe factory has a maximum of 120 labour hours and 110 units of raw material available per day.\nThe profit on one unit of A is ₹50, and on one unit of B is ₹40.\nIf the company wants to maximize profit, what is the maximum profit they can earn?','₹1800','₹2000','₹2200','₹2400',NULL,NULL,'B',2,NULL,NULL,NULL,'English',5,NULL,'5',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Chemistry'),(1308,NULL,'Lanthanoid contraction is responsible for the similarity in radii of:','Na and K','Fe and Co','Zr and Hf','Cu and Ag',NULL,NULL,'D',2,NULL,NULL,NULL,'English',6,NULL,'6',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ','II','Chemistry'),(1430,NULL,'Assertion: Heavy water is preferred over ordinary water as moderator in reactors. Reason: Heavy water, used for slowing down the neutrons, has lesser absorption probability of neutrons than ordinary water.','Both Assertion & Reason are True & the Reason is a correct explanation of the Assertion.','Both Assertion & Reason are True but Reason is not a correct explanation of the Assertion.','Assertion is True but the Reason is False.','Both Assertion & Reason are False.',NULL,NULL,'B',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,'Ques_img_1.png',NULL,NULL,NULL,NULL,'MCQ',NULL,NULL),(1431,NULL,'Which of the following sets cannot enter into the list of fundamental quantities in any newly proposed system of units? (a) length, mass and velocity (b) pressure, density and velocity (c) force, velocity and time (d) force, momentum and time','a and c','b and d','only d','only a',NULL,NULL,'C',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ',NULL,NULL),(1432,NULL,'A body starts from rest with a uniform acceleration of $2~m/s^{2}$ for 10 s then, it moves with constant speed for 30 s, then decelerates by $4~m/s^{2}$ to become at rest. The distance covered by the body:','750 m','850 m','600 m','None of these',NULL,NULL,'B',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ',NULL,NULL),(1433,NULL,'A body of mass 1 kg is thrown vertically upwards with $20~m/s.$ If it again reaches ground with a speed of $16~m/s,$ then find work done by Air resistance in whole journey.','$-144~J$','$-72~J$','$-70~J$','$256~J$',NULL,NULL,'C',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ',NULL,NULL),(1434,NULL,'A ball is moving with velocity $2~m/s$ towards a heavy wall moving towards the ball with speed $1~m/s$ as shown in figure. Assuming collision to be elastic, the velocity of ball immediately after collision is: (Assuming figure implies $2~m/s$ is $\\hat{i}$ and $1~m/s$ is $-\\hat{i}$ for calculation, direction is not specified in text)','$4\\hat{i}~m/s$','$2\\hat{i}~m/s$','$-4\\hat{i}~m/s$','$-2\\hat{i}~m/s$',NULL,NULL,'C',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ',NULL,NULL),(1435,NULL,'A weightless thread can support tension upto 30 N. A stone of mass 0.5 kg is tied to it and is revolved in a circular path of radius 2m in a vertical plane. If $g=10~ms^{-2}$ then the maximum angular velocity of the stone will be:','$5~rad/s$','$\\sqrt{30}~rad/s$','$\\sqrt{60}~rad/s$','$10~rad/s$',NULL,NULL,'C',13,NULL,NULL,NULL,'English',4,1.00,'1',NULL,NULL,'Yes',NULL,NULL,NULL,NULL,NULL,NULL,'MCQ',NULL,NULL)