CREATE TABLE `students` (
  `id` int NOT NULL AUTO_INCREMENT,
  `roll_number` varchar(50) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `address_line_1` text,
  `password` varchar(255) DEFAULT NULL,
  `student_exam_id` int DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `pincode` varchar(10) DEFAULT NULL,
  `student_picture` varchar(200) DEFAULT NULL,
  `date_of_birth` varchar(45) DEFAULT NULL,
  `capture` mediumtext,
  `capt_datetime` datetime DEFAULT NULL,
  `is_disabled` varchar(1) DEFAULT NULL,
  `adhar_number` varchar(15) DEFAULT NULL,
  `Category` varchar(20) DEFAULT NULL,
  `application_numbe` varchar(20) DEFAULT NULL,
  `father_name` varchar(45) DEFAULT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `address_line_2` varchar(100) DEFAULT NULL,
  `alternate_phone_number` varchar(15) DEFAULT NULL,
  `mother_name` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `roll_number` (`roll_number`),
  KEY `student_exam_id_idx` (`student_exam_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4403 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
