CREATE DEFINER=`dep1992`@`%` PROCEDURE `process_leaves`(IN forMonth int, IN forYear int)
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE l_start_date DATE;
    DECLARE l_end_date DATE;
    DECLARE l_emp_id INT;
    DECLARE l_emp_name VARCHAR(100);
    DECLARE l_attend_status CHAR(1);
    DECLARE l_current_date DATE;
    
    DECLARE cur CURSOR FOR
		SELECT 
			emp.emp_id, 
            concat(trim(emp.emp_first_name), ' ', trim(emp.emp_last_name)) as l_emp_name, 
			elt.emp_leave_start_date as l_start_date, 
			elt.emp_leave_end_date as l_end_date, 
			CASE UPPER(elt.emp_leave_tran_leave_type) WHEN 'OPTIONAL' THEN 'O' WHEN 'UNPAID LEAVE' THEN 'U' ELSE 'L' END as l_attend_status
        FROM emp_leave_transactions elt, employee emp 
		WHERE elt.emp_leave_tran_emp_id = emp.emp_id
		AND (
				(month(elt.emp_leave_start_date) = forMonth and year(elt.emp_leave_start_date) = forYear) OR 
                (month(elt.emp_leave_end_date) = forMonth and year(elt.emp_leave_end_date) = forYear)
			);

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO l_emp_id, l_emp_name, l_start_date, l_end_date, l_attend_status;

        IF done THEN
            LEAVE read_loop;
        END IF;

        SET l_current_date = l_start_date;

        -- Loop to generate insert statements for each day between start_date and end_date
        WHILE l_current_date <= l_end_date DO
            -- Create records against leaves in the employee attendance table
			INSERT INTO emp_attendance (emp_attend_emp_id, emp_attend_name, emp_attend_date, emp_attend_status)
            VALUES (l_emp_id, l_emp_name, l_current_date, l_attend_status)
            ON DUPLICATE KEY UPDATE
            emp_attend_status = IF(emp_attend_status not in ('X', 'Y', 'Z'), l_attend_status, emp_attend_status);
            
            -- Move to the next day
            SET l_current_date = DATE_ADD(l_current_date, INTERVAL 1 DAY);
        END WHILE;
    END LOOP;
    CLOSE cur;
commit;
END ;;
DELIMITER ;
